style.css:
/* Dark purple background theme */
body {
  position: relative;
  min-height: 100vh;
  margin: 0;
  background: none;
  overflow-x: hidden;
}

/* Gradient base */
body::before {
  content: "";
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: -2;

  background: linear-gradient(135deg, #2e003e, #4b0082, #3a0ca3, #2e003e);
  background-size: 300% 300%;
  animation: darkShift 20s ease infinite;
}

/* Soft swirls */
body::after {
  content: "";
  position: fixed;
  top: 0;
  left: 0;
  width: 200%;
  height: 200%;
  z-index: -1;
  pointer-events: none;

  background-image: repeating-radial-gradient(
      circle at 20% 20%,
      rgba(255, 255, 255, 0.08) 0,
      transparent 80px
    ),
    repeating-radial-gradient(
      circle at 80% 80%,
      rgba(255, 255, 255, 0.06) 0,
      transparent 100px
    ),
    repeating-radial-gradient(
      circle at 50% 50%,
      rgba(255, 255, 255, 0.04) 0,
      transparent 120px
    );
  background-size: 400px 400px, 600px 600px, 800px 800px;
  animation: swirlFloat 70s linear infinite;
}

/* Gradient animation */
@keyframes darkShift {
  0%   { background-position: 0% 50%; }
  50%  { background-position: 100% 50%; }
  100% { background-position: 0% 50%; }
}

/* Swirl drifting animation */
@keyframes swirlFloat {
  0%   { transform: rotate(0deg) translate(0,0); }
  50%  { transform: rotate(25deg) translate(-60px,-40px); }
  100% { transform: rotate(0deg) translate(0,0); }
}

/* === TEXT COLORS === */
/* Force default (black) text to white */
body, body * {
  color: #ffffff;
}

/* Flip explicitly white text into dark purple */
body *[style*="color: white"],
body *[style*="color:#fff"],
body *[style*="color:#ffffff"] {
  color: #2e003e !important;
}

/* === BACKGROUND COLORS === */
/* Change all white backgrounds to lavender */
body *[style*="background: white"],
body *[style*="background:#fff"],
body *[style*="background:#ffffff"],
body *[style*="background-color: white"],
body *[style*="background-color:#fff"],
body *[style*="background-color:#ffffff"] {
  background-color: #e6e6fa !important; /* lavender */
}

/* Fallback: any element with default white background */
body * {
  background-color: transparent;
}

/* Images and graphics with white background — tint with lavender */
img {
  background-color: #e6e6fa; /* lavender frame */
}
